import s from './BarberSidebar.module.css'
import Brand from './Brand'
import FindUs from './FindUs'
import SocialLinks from './SocialLinks'

export default function BarberSidebar({ data: d }) {
  const services = Array.isArray(d.services) ? d.services : []
  const gallery = Array.isArray(d.gallery) ? d.gallery : []
  const story = Array.isArray(d.story) ? d.story : []
  const phoneHref = d.PHONE_INTL
    ? 'tel:' + d.PHONE_INTL
    : d.PHONE
      ? 'tel:' + d.PHONE
      : null

  return (
    <div className={s.root}>
      <nav className={s.nav} aria-label='Κύρια πλοήγηση'>
        <div className={s.navInner}>
          <a href='#home' className={s.logo}>
            <Brand data={d} className={s.brand} dark />
          </a>
          <div className={s.navLinks}>
            <a href='#home'>Αρχική</a>
            <a href='#story'>Ιστορία</a>
            <a href='#services'>Υπηρεσίες</a>
            <a href='#pricing'>Τιμοκατάλογος</a>
            <a href='#contact'>Επικοινωνία</a>
          </div>
        </div>
      </nav>

      <main className={s.main}>
        <header id='home' className={s.hero}>
          {d.HERO_IMAGE ? <img src={d.HERO_IMAGE} alt='' className={s.heroImage} /> : null}
          <div className={s.heroOverlay} aria-hidden='true'></div>
          <div className={s.heroContent}>
            {d.KICKER ? <p className={s.kicker}>{d.KICKER}</p> : null}
            <h1 className={s.heroTitle}>{d.NAME || d.HERO_WORD}</h1>
            {d.INTRO || d.TAGLINE ? (
              <p className={s.heroTagline}>{d.INTRO || d.TAGLINE}</p>
            ) : null}
            <div className={s.heroActions}>
              <a className={s.heroButton} href='#story'>Η ιστορία μας</a>
              <a className={s.heroButtonGhost} href='#services'>Οι υπηρεσίες μας</a>
            </div>
          </div>
        </header>

        {story.length > 0 ? (
          <section id='story' className={s.section}>
            <div className={s.sectionInner}>
              <div className={s.storyGrid}>
                <div className={s.storyBody}>
                  <p className={s.eyebrow}>Η ιστορία μας</p>
                  <h2 className={s.sectionTitle}>{d.STORY_TITLE || 'Η ιστορία μας'}</h2>
                  {story.map((item, i) => (
                    <p key={i} className={s.storyParagraph}>{item.p}</p>
                  ))}
                </div>
                {d.STORY_IMAGE ? (
                  <div className={s.storyImageWrap}>
                    <img src={d.STORY_IMAGE} alt={d.STORY_TITLE || ''} className={s.storyImage} />
                  </div>
                ) : null}
              </div>
            </div>
          </section>
        ) : null}

        {gallery.length > 0 ? (
          <section id='portfolio' className={s.section}>
            <div className={s.sectionInner}>
              <p className={s.eyebrow}>Έργα</p>
              <h2 className={s.sectionTitle}>Πρόσφατα κουρέματα</h2>
              <div className={s.galleryGrid}>
                {gallery.map((item, i) => (
                  <figure className={s.galleryCard} key={i}>
                    {item.image ? <img src={item.image} alt={item.title || ''} loading='lazy' className={s.galleryImage} /> : null}
                    {item.title || item.sub ? (
                      <figcaption className={s.galleryCaption}>
                        {item.title ? <h3>{item.title}</h3> : null}
                        {item.sub ? <p>{item.sub}</p> : null}
                      </figcaption>
                    ) : null}
                  </figure>
                ))}
              </div>
            </div>
          </section>
        ) : null}

        {services.length > 0 ? (
          <section id='services' className={s.section}>
            <div className={s.sectionInner}>
              <p className={s.eyebrow}>Υπηρεσίες</p>
              <h2 className={s.sectionTitle}>Τι προσφέρουμε</h2>
              <div className={s.servicesGrid}>
                {services.map((item, i) => {
                  const media = gallery[i]
                  const image = media ? media.image : null
                  const alt = media && media.title ? media.title : item.title || ''
                  return (
                    <article className={s.serviceCard} key={i}>
                      {image ? <img src={image} alt={alt} loading='lazy' className={s.serviceImage} /> : null}
                      <div className={s.serviceInfo}>
                        <h3 className={s.serviceTitle}>{item.title}</h3>
                        {item.desc ? <p className={s.serviceDesc}>{item.desc}</p> : null}
                        {item.duration ? <span className={s.serviceDuration}>{item.duration}</span> : null}
                      </div>
                      {item.price ? <span className={s.servicePrice}>{item.price}</span> : null}
                    </article>
                  )
                })}
              </div>
            </div>
          </section>
        ) : null}

        {services.length > 0 ? (
          <section id='pricing' className={s.section}>
            <div className={s.sectionInner}>
              <div className={s.pricingHeader}>
                <div>
                  <p className={s.eyebrow}>Τιμοκατάλογος</p>
                  <h2 className={s.sectionTitle}>Η λίστα τιμών μας</h2>
                </div>
                {services[0] && services[0].price ? (
                  <strong className={s.priceStarting}>Από {services[0].price}</strong>
                ) : null}
              </div>
              <ul className={s.priceList}>
                {services.map((item, i) => (
                  <li className={s.priceItem} key={i}>
                    <span className={s.priceName}>
                      {item.title}
                      {item.duration ? <span className={s.priceDuration}> · {item.duration}</span> : null}
                    </span>
                    <span className={s.priceDivider} aria-hidden='true'></span>
                    {item.price ? <strong className={s.priceValue}>{item.price}</strong> : null}
                  </li>
                ))}
              </ul>
            </div>
          </section>
        ) : null}

        <section id='contact' className={s.section}>
          <div className={s.sectionInner}>
            <p className={s.eyebrow}>Επικοινωνία</p>
            <h2 className={s.sectionTitle}>{d.CTA_TITLE || 'Πες ένα γεια'}</h2>
            <div className={s.contactGrid}>
              <div className={s.contactInfo}>
                {d.PHONE && phoneHref ? (
                  <a className={s.contactLink} href={phoneHref}>{d.PHONE}</a>
                ) : null}
                {d.DOMAIN ? (
                  <a className={s.contactDomain} href={'https://' + d.DOMAIN} target='_blank' rel='noreferrer'>{d.DOMAIN}</a>
                ) : null}
                {d.AREAS ? <p className={s.contactArea}>{d.AREAS}</p> : null}
                {d.TRADE || d.CITY ? (
                  <p className={s.contactMeta}>
                    {d.TRADE ? <span>{d.TRADE}</span> : null}
                    {d.TRADE && d.CITY ? ' · ' : null}
                    {d.CITY ? <span>{d.CITY}</span> : null}
                    {d.POSTCODE ? <span> {d.POSTCODE}</span> : null}
                  </p>
                ) : null}
                <SocialLinks data={d} className={s.social} />
              </div>
              <div className={s.openWrap}>
                <div className={s.openCard}>
                  <h3>Ανοιχτά καθημερινά</h3>
                  {d.HOURS ? <p className={s.openHours}>{d.HOURS}</p> : null}
                </div>
              </div>
            </div>
            <div className={s.findUs}>
              <FindUs data={d} />
            </div>
          </div>
        </section>
      </main>

      <footer className={s.footer}>
        <div className={s.footerInner}>
          {d.YEAR || d.NAME ? <p>© {d.YEAR || ''} {d.NAME || ''}. Με επιφύλαξη παντός δικαιώματος.</p> : null}
          <a href='#home' className={s.backTop}>Επιστροφή στην αρχή</a>
        </div>
      </footer>
    </div>
  )
}

.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #171412;
  --vt-ink: #131313;
  --vt-ink-soft: #6e6f72;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #171412;
  --vt-accent-ink: #7a4c08;
  --vt-accent-on-deep: #d6a354;
  --vt-line: #d9d9d9;
  --vt-font-body: 'Inter', 'Arial', sans-serif;
  --vt-font-display: 'Anton', 'Arial', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: var(--vt-font-body);
  line-height: 1.6;
  scroll-behavior: smooth;
}
.root,
.root * {
  box-sizing: border-box;
}
.root :where(a) {
  color: inherit;
  text-decoration: none;
}
.root a:focus-visible,
.root button:focus-visible {
  outline: 3px solid var(--vt-accent);
  outline-offset: 3px;
}
.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0 0 0.4em;
}
.nav {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 280px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  z-index: 100;
  display: flex;
}
.navInner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  padding: 40px 24px;
  gap: 48px;
}
.logo {
  display: block;
}
.brand {
  display: inline-block;
  font-family: var(--vt-font-display);
  font-size: 1.5rem;
  line-height: 1.1;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.navLinks {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
}
.navLinks a {
  color: var(--vt-on-accent);
  font-weight: 700;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  padding: 4px 0;
}
.navLinks a:hover {
  color: var(--vt-on-deep);
}
.main {
  margin-left: 280px;
}
.hero {
  position: relative;
  min-height: 665px;
  display: flex;
  align-items: center;
  overflow: hidden;
  padding: 50px;
  border-bottom: 10px solid var(--vt-accent);
  color: var(--vt-on-deep);
}
.heroImage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 0;
}
.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-surface-deep);
  opacity: 0.45;
  z-index: 1;
}
.heroContent {
  position: relative;
  z-index: 2;
  max-width: 680px;
}
.kicker {
  color: var(--vt-accent-on-deep);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.85rem;
  margin-bottom: 12px;
}
.heroTitle {
  font-family: var(--vt-font-display);
  font-size: clamp(3rem, 8vw, 6rem);
  line-height: 0.95;
  text-transform: uppercase;
  color: var(--vt-on-deep);
  margin-bottom: 16px;
}
.heroTagline {
  color: var(--vt-on-deep);
  font-size: 1.15rem;
  max-width: 42rem;
  opacity: 0.92;
}
.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}
.heroButton,
.heroButtonGhost {
  display: inline-block;
  border-radius: 100px;
  padding: 12px 24px;
  font-weight: 700;
  line-height: 1.2;
  transition: background 0.3s, color 0.3s, border-color 0.3s;
}
.heroButton {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border: 2px solid var(--vt-accent);
}
.heroButton:hover {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  border-color: var(--vt-surface-deep);
}
.heroButtonGhost {
  background: transparent;
  color: var(--vt-on-deep);
  border: 2px solid var(--vt-on-deep);
}
.heroButtonGhost:hover {
  background: var(--vt-on-deep);
  color: var(--vt-surface-deep);
  border-color: var(--vt-on-deep);
}
.section {
  padding: 100px 50px;
}
.sectionInner {
  max-width: 1200px;
  margin: 0 auto;
}
.eyebrow {
  color: var(--vt-accent-ink);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.8rem;
  margin-bottom: 8px;
}
.sectionTitle {
  font-family: var(--vt-font-display);
  font-size: clamp(2.2rem, 5vw, 3.5rem);
  line-height: 1;
  text-transform: uppercase;
  color: var(--vt-ink);
  margin-bottom: 24px;
}
.storyGrid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 60px;
  align-items: center;
}
.storyParagraph {
  color: var(--vt-ink-soft);
  font-size: 1.05rem;
  margin-bottom: 16px;
}
.storyImageWrap {
  position: relative;
}
.storyImage {
  display: block;
  width: 100%;
  height: 480px;
  object-fit: cover;
  border-radius: 20px;
  box-shadow: 0 20px 40px var(--vt-line);
}
.galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.galleryCard {
  position: relative;
  margin: 0;
  overflow: hidden;
  border-radius: 20px;
  background: var(--vt-surface-2);
}
.galleryImage {
  display: block;
  width: 100%;
  height: 280px;
  object-fit: cover;
  transition: transform 0.4s;
}
.galleryCard:hover .galleryImage {
  transform: scale(1.05);
}
.galleryCaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 20px;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}
.galleryCaption h3 {
  font-family: var(--vt-font-body);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 2px;
  color: var(--vt-on-deep);
}
.galleryCaption p {
  margin: 0;
  color: var(--vt-on-deep);
  opacity: 0.85;
  font-size: 0.9rem;
}
.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}
.serviceCard {
  position: relative;
  overflow: hidden;
  border-radius: 20px;
  border: 1px solid var(--vt-line);
  background: var(--vt-surface-2);
}
.serviceImage {
  display: block;
  width: 100%;
  height: 320px;
  object-fit: cover;
  transition: transform 0.4s;
}
.serviceCard:hover .serviceImage {
  transform: scale(1.05);
}
.serviceInfo {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 24px;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}
.serviceTitle {
  font-family: var(--vt-font-body);
  font-size: 1.25rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--vt-on-deep);
  margin-bottom: 4px;
}
.serviceDesc {
  margin: 0;
  color: var(--vt-on-deep);
  opacity: 0.85;
  font-size: 0.95rem;
}
.serviceDuration {
  display: block;
  margin-top: 8px;
  color: var(--vt-accent-on-deep);
  font-size: 0.82rem;
}
.servicePrice {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 2;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 999px;
  padding: 8px 16px;
  font-size: 0.9rem;
  font-weight: 700;
  box-shadow: 0 4px 12px var(--vt-surface-deep);
}
.pricingHeader {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  margin-bottom: 32px;
}
.priceStarting {
  color: var(--vt-ink-soft);
  font-weight: 700;
}
.priceList {
  list-style: none;
  margin: 0;
  padding: 0;
}
.priceItem {
  display: flex;
  align-items: baseline;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--vt-line);
}
.priceName {
  white-space: nowrap;
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--vt-ink);
}
.priceDuration {
  margin-left: 8px;
  font-weight: 400;
  font-size: 0.85rem;
  color: var(--vt-ink-soft);
}
.priceDivider {
  flex: 1;
  border-bottom: 2px dotted var(--vt-ink-soft);
  transform: translateY(-4px);
}
.priceValue {
  white-space: nowrap;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--vt-accent-ink);
}
.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-top: 40px;
}
.contactInfo {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.contactLink {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--vt-ink);
}
.contactDomain {
  color: var(--vt-accent-ink);
  font-weight: 700;
}
.contactArea,
.contactMeta {
  margin: 0;
  color: var(--vt-ink-soft);
}
.social {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}
.openWrap {
  display: flex;
  align-items: stretch;
}
.openCard {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 20px;
  padding: 32px;
  transform: rotate(2deg);
  box-shadow: 0 12px 24px var(--vt-line);
  flex: 1;
}
.openCard h3 {
  font-family: var(--vt-font-body);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 14px;
  color: var(--vt-on-accent);
}
.openHours {
  margin: 0;
  font-size: 1.6rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--vt-on-accent);
}
.findUs {
  margin-top: 48px;
  padding: 24px;
  border: 1px solid var(--vt-line);
  border-radius: 20px;
  background: var(--vt-surface-2);
}
.footer {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 32px 50px;
}
.footerInner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}
.footerInner p {
  margin: 0;
  color: var(--vt-on-deep);
  opacity: 0.85;
}
.backTop {
  color: var(--vt-accent-on-deep);
  font-weight: 700;
}
@media (max-width: 991px) {
  .nav {
    position: relative;
    width: 100%;
    height: auto;
  }
  .navInner {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    height: auto;
    padding: 16px 24px;
    gap: 16px;
  }
  .navLinks {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 14px;
  }
  .main {
    margin-left: 0;
  }
  .section {
    padding: 60px 24px;
  }
  .hero {
    min-height: 520px;
    padding: 40px 24px;
  }
  .storyGrid {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .storyImage {
    height: 360px;
  }
  .galleryGrid {
    grid-template-columns: repeat(2, 1fr);
  }
  .servicesGrid {
    grid-template-columns: 1fr;
  }
  .contactGrid {
    grid-template-columns: 1fr;
  }
  .footer {
    padding: 24px;
  }
  .footerInner {
    flex-direction: column;
    text-align: center;
  }
}
@media (max-width: 640px) {
  .galleryGrid {
    grid-template-columns: 1fr;
  }
  .heroContent {
    padding: 20px 0;
  }
  .heroTitle {
    font-size: 2.6rem;
  }
  .heroActions {
    flex-direction: column;
  }
  .heroButton,
  .heroButtonGhost {
    text-align: center;
  }
  .pricingHeader {
    flex-direction: column;
    align-items: flex-start;
  }
  .serviceImage {
    height: 280px;
  }
}
